<script setup lang="ts">
import type { Product, Purchase, SaveProductInput } from '../api'
const props=defineProps<{products:Product[];purchases:Purchase[];busy:boolean}>()
const emit=defineEmits<{save:[value:SaveProductInput];archive:[product:Product];reconcile:[order:Purchase,result:'success'|'failed']}>()
const defaults=():SaveProductInput=>({category:'LDC',name:'',description:'',points_price:500,ldc_amount:'1.00',user_daily_limit:1,total_daily_limit:10,is_active:true})
const form=reactive<SaveProductInput>(defaults())
function reset(){Object.assign(form,defaults());delete form.id}
function edit(item:Product){Object.assign(form,{id:item.id,category:'LDC',name:item.name,description:item.description||'',points_price:item.points_price,ldc_amount:item.ldc_amount||'1.00',user_daily_limit:item.user_daily_limit||0,total_daily_limit:item.total_daily_limit||0,is_active:item.is_active})}
defineExpose({ reset })
const names:Record<string,string>={success:'自动发货成功',simulated:'模拟发货成功',pending:'处理中',failed:'失败 (已退还积分)',uncertain:'待人工核对'}
</script>
<template><section id="sec-products" style="margin-bottom:36px"><h2 style="font-size:20px;font-weight:700;margin:0 0 16px">商品管理</h2><div style="display:grid;grid-template-columns:340px minmax(0,1fr);gap:20px;margin-bottom:24px"><div class="card"><h3 style="font-size:16px;font-weight:700;margin:0 0 16px">{{ form.id?`编辑商品 #${form.id}`:'添加上架商品' }}</h3><form @submit.prevent="emit('save',{...form})"><div class="form-group"><label class="form-label">选择品类</label><select v-model="form.category" class="input-select"><option value="LDC">LDC 自动发货</option></select></div><div class="form-group"><label class="form-label">商品名称</label><input v-model.trim="form.name" class="input-text" maxlength="80" required></div><div class="form-group"><label class="form-label">商品介绍</label><textarea v-model.trim="form.description" class="input-textarea" rows="2" maxlength="500" /></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="form-group"><label class="form-label">积分售价</label><input v-model.number="form.points_price" class="input-text" type="number" min="0" max="100000000" required></div><div class="form-group"><label class="form-label">LDC 发货数量</label><input v-model="form.ldc_amount" class="input-text" type="number" min="0.01" max="10000" step="0.01" required></div><div class="form-group"><label class="form-label">单人每日限购</label><input v-model.number="form.user_daily_limit" class="input-text" type="number" min="0" max="100000"></div><div class="form-group"><label class="form-label">全站总数限购</label><input v-model.number="form.total_daily_limit" class="input-text" type="number" min="0" max="100000"></div></div><div class="form-group" style="display:flex;gap:8px"><input v-model="form.is_active" type="checkbox"><label>立即上架在商店展示</label></div><div style="display:flex;gap:10px"><button class="btn-primary" type="submit" style="flex:1" :disabled="busy">保存商品</button><button class="btn-secondary" type="button" :disabled="busy" @click="reset">重置</button></div></form></div>
<details class="card card-collapse" open><summary class="collapse-summary"><h3 class="card-title">商品列表 (LDC 品类)</h3></summary><div class="collapse-body"><div class="table-wrap" style="max-height:380px"><table class="data-table" style="min-width:680px"><thead><tr><th>ID</th><th>品类</th><th>名称</th><th>售价</th><th>发货数量</th><th>每日限购</th><th>状态</th><th class="cell-sticky-end">操作</th></tr></thead><tbody><tr v-if="!products.length"><td colspan="8" style="text-align:center">暂无商品记录，在左侧表单中添加商品。</td></tr><tr v-for="item in products" :key="item.id"><td>#{{ item.id }}</td><td>{{ item.category||'LDC' }}</td><td>{{ item.name }}</td><td>{{ item.points_price }} 分</td><td>{{ item.ldc_amount }} LDC</td><td>{{ item.user_daily_limit>0?`${item.user_daily_limit} 份/人`:'不限' }} / {{ item.total_daily_limit>0?`${item.total_daily_limit} 份/天`:'不限' }}</td><td>{{ item.is_active?'在售中':'已下架' }}</td><td class="cell-sticky-end"><button class="btn-secondary" type="button" :disabled="busy" @click="edit(item)">编辑</button> <button v-if="item.is_active" class="btn-secondary" type="button" :disabled="busy" style="color:#dc2626" @click="emit('archive',item)">下架</button></td></tr></tbody></table></div></div></details></div>
<details class="card card-collapse" open><summary class="collapse-summary"><div><h3 class="card-title">自动发货与兑换记录</h3><span class="card-subtitle">用户积分购买商品后的实时发货流水状态</span></div></summary><div class="collapse-body"><div class="table-wrap" style="max-height:320px"><table class="data-table" style="min-width:900px"><thead><tr><th>订单号</th><th>用户</th><th>商品 / LDC</th><th>消耗积分</th><th>发货状态</th><th>单号 / 错误</th><th>时间</th><th class="cell-sticky-end">操作</th></tr></thead><tbody><tr v-if="!purchases.length"><td colspan="8" style="text-align:center">暂无用户兑换与发货记录。</td></tr><tr v-for="item in purchases" :key="item.order_no"><td style="font-family:monospace">{{ item.order_no }}</td><td>@{{ item.username }}</td><td>{{ item.product_name.includes(item.ldc_amount)?item.product_name:`${item.product_name} (${item.ldc_amount} LDC)` }}</td><td>-{{ item.points_cost }} 分</td><td>{{ names[item.status]||item.status }}</td><td>{{ item.trade_no||item.error||'—' }}</td><td>{{ item.created_at }}</td><td class="cell-sticky-end"><template v-if="item.status==='uncertain'"><button class="btn-secondary" type="button" :disabled="busy" @click="emit('reconcile',item,'success')">已发货</button> <button class="btn-secondary" type="button" :disabled="busy" style="color:#dc2626" @click="emit('reconcile',item,'failed')">未发货并退分</button></template><template v-else>—</template></td></tr></tbody></table></div></div></details></section></template>
